fn main() {
    let r = Rec { tag: 1, x: 2.5 };
    let p: *const f64 = &raw const r.x;
    let q: *const f64 = core::ptr::addr_of!(r.x);
    // SAFETY: p points at an initialized f64 inside r; read_unaligned tolerates the packing.
